"""Visual notes for tables/figures whose content is NOT recoverable from the PDF text layer
(tables have scrambled number glyphs; charts, maps and diagrams are raster/vector graphics).
Authoring method: each page below was rendered at 105 dpi and read by Claude (vision) -> transcribed here.
Written BEFORE the benchmark questions. Values read from charts are marked 'xấp xỉ' when not printed on the chart.
Source of every item: World Bank, Việt Nam: Báo cáo Quốc gia về Khí hậu và Phát triển (CCDR), 07/2022."""
import json
N = []
def add(page, kind, fid, title, text): N.append({"page": page, "type": kind, "figure_id": fid, "title": title, "text": text})

add(13,"figure","Hình 1","Mô hình phát triển mới cho Việt Nam","Sơ đồ (diagram) có hai khối chính: khối trên 'Việt Nam hiện nay' (màu xanh) và khối dưới 'Việt Nam năm 2045' (màu cam), nối bằng hai mũi tên cong: bên trái 'Lộ trình xây dựng khả năng chống chịu', bên phải 'Hành trình khử carbon'. Ở giữa là danh sách năm hành động: xây dựng cơ sở hạ tầng có khả năng chống chịu; bảo vệ những đối tượng bị tổn thương nhất; cải cách cơ cấu để khuyến khích nông dân và doanh nghiệp; định giá carbon; huy động nguồn vốn.")
add(15,"figure","Hình 2","Để trở thành quốc gia thu nhập cao vào năm 2045, Việt Nam cần đạt được tốc độ tăng trưởng cao hơn","Biểu đồ đường: GDP bình quân đầu người (USD 2015 cố định) theo thời gian T đến T+54 (T là năm mà các nước khác có GDP bình quân đầu người bằng Việt Nam năm 1990). Sáu chuỗi: Hàn Quốc (1951-2005), Thái Lan (1958-2012), Trung Quốc (1983-2020), Việt Nam (1990-2020), Việt Nam (2021-2045, đường đứt nét), và Ngưỡng HIC (quốc gia có thu nhập cao, đường ngang xấp xỉ 12.500-12.695). Hàn Quốc vượt ngưỡng HIC khoảng T+42 và đạt xấp xỉ 21.000 ở cuối chuỗi; Việt Nam (2021-2045) chạm ngưỡng HIC ở cuối chuỗi (khoảng T+54, xấp xỉ 12.000); Thái Lan chỉ đạt xấp xỉ 5.500 ở cuối chuỗi; Trung Quốc đạt xấp xỉ 10.500 ở khoảng T+36.")
add(17,"figure","Hình 3","Chi phí ước tính do biến đổi khí hậu năm 2020 (triệu USD)","Biểu đồ treemap (ô chữ nhật theo diện tích) với giá trị in trên từng ô, đơn vị triệu USD: Thủy sản 4219 (ô lớn nhất); Năng suất lao động 2807; Mực nước biển dâng 1474; Nông nghiệp 837; Chi phí giải nhiệt 518; Thiên tai 447; Sức khỏe 235; Nước 218; Du lịch 148. Nguồn: Ngân hàng Thế giới, 2021.")
add(18,"figure","Hình 4","Gia tăng mức phát thải GHG","Biểu đồ vùng xếp chồng (stacked area): phát thải GHG theo ngành (MtCO2e) từ 1990 đến 2018, trục tung từ -100 đến 400. Tổng phát thải tăng từ khoảng 75 MtCO2e năm 1990 lên khoảng 380 MtCO2e năm 2018. Các ngành trong chú giải: Điện/Nhiệt, Nông nghiệp, Công trình xây dựng, Quy trình công nghiệp, Giao thông, Chất thải, Khí thải từ các bình áp suất, Cơ sở, Dầu thô, Các loại nhiên liệu khác, Thay đổi mục đích sử dụng đất và lâm nghiệp. Ngành thay đổi mục đích sử dụng đất và lâm nghiệp có giá trị âm (khoảng -70 giai đoạn 1990-2000, khoảng -12 năm 2018).")
add(19,"table","Bảng 1","So sánh phát thải giữa các nước","Bảng 1 (Nguồn: Climate Watch). Các cột: Nước | Phát thải trên đầu người (tCO2e trên đầu người) | Phát thải Carbon (tCO2e/triệu $GDP) | Tổng phát thải (MtCO2e) | % phát thải toàn cầu. Hàng: Hoa Kỳ 17,7 | 281,5 | 5.794,3 | 12,0%. Mông Cổ 17,5 | 4.250,9 | 55,7 | 0,1%. Malaysia 12,3 | 1.08,9 | 388,1 | 0,8%. OECD 10,8 | 266,6 | 14.081,8 | 29,8%. Đức 9,4 | 195,9 | 776,61 | 1,6%. Trung Quốc 8,4 | 842,5 | 11.705,1 | 23,9%. Papua New Guinea 7,5 | 2.658,3 | 64,1 | 0,1%. Vương quốc Anh 6,6 | 154,2 | 441,1 | 0,9%. Indonesia 6,4 | 1.634,8 | 1.703,9 | 3,6%. Thái Lan 6,2 | 851,4 | 431,2 | 0,9%. Lào 5,5 | 2.151,6 | 38,6 | 0,1%. Pháp 5,4 | 129,6 | 361,4 | 0,7%. Đông Timor 5,3 | 4.271,0 | 6,7 | 0,0%. Thổ Nhĩ Kỳ 5 | 603,9 | 422,0 | 1,0%. Myanmar 4,3 | 3.040,9 | 231,6 | 0,5%. Campuchia 4,3 | 2.814,1 | 69,2 | 0,1%. Việt Nam 3,8 | 1.486,2 | 364,4 | 0,8%. Philipin 2,2 | 677,0 | 234,8 | 0,5%.")
add(19,"figure","Hình 5","Phát thải GHG trên đầu người (tấn/đầu người) (Chấm đỏ là Việt Nam)","Biểu đồ phân tán (scatter): trục hoành là GDP trên đầu người (0 đến 30000), trục tung là phát thải GHG trên đầu người (0 đến 35 tấn). Mỗi chấm xanh là một quốc gia; chấm đỏ là Việt Nam, nằm ở khoảng GDP đầu người xấp xỉ 2.700 và phát thải xấp xỉ 4 tấn/người (thấp so với nhiều nước có thu nhập cao hơn). Điểm cao nhất xấp xỉ 31 tấn/người ở GDP đầu người xấp xỉ 24.000. Nguồn: ClimateWatch.")
add(25,"figure","Hình 6","Các tác động của biến đổi khí hậu và rủi ro thiên tai dưới sự quan sát của các doanh nghiệp (2019)","Biểu đồ cột ngang xếp chồng 100%: phần trăm doanh nghiệp báo cáo, theo bốn mức Hầu như không / Khá ít / Tương đối nhiều / Rất nhiều. Các hàng (bốn số theo thứ tự trên): Giai đoạn kinh doanh sản xuất 11/35/38/16; Giảm năng suất lao động 12/37/38/13; Doanh thu sụt giảm 12/37/35/16; Gián đoạn kênh vận chuyển 16/38/33/13; Tăng chi phí sản xuất 16/39/35/9; Trì hoãn mạng lưới phân phối 24/38/28/10; Giảm chất lượng sản phẩm/dịch vụ 27/36/26/11; Thiệt hại về cơ sở vật chất 21/45/25/9; Thiếu hụt nhân lực 24/43/25/8; Thiếu nguồn cung nguyên liệu đầu vào 33/34/24/9. Ghi chú: tóm tắt ý kiến của hơn 10.000 doanh nghiệp trong khảo sát năm 2019 (VCCI, 2020).")
add(26,"figure","Hình 7","Biến thiên tỷ trọng sản lượng của các DNNN trong các ngành công nghiệp sử dụng nhiều carbon tại Việt Nam (%)","Biểu đồ đường 2005-2018 (sơ bộ), nhãn giá trị năm 2018: Than 98%; Phân hóa học 94%; Điện 85%; Vận tải hàng hóa 55%; Phân bón NPK 55%; Xi măng 35%; Vận chuyển hành khách 27%; Kim loại 14%. Năm 2005 ngành Điện xấp xỉ 95% rồi giảm xuống xấp xỉ 70% quanh 2007 trước khi tăng lại; Kim loại giảm từ xấp xỉ 33% (2005) xuống 14%.")
add(30,"figure","Hình 8","Các tác động kinh tế ước tính khi nhiệt độ và lượng mưa cao hơn, thay đổi nhiều hơn, mực nước biển dâng cao - thiệt hại GDP","Biểu đồ đường 2022-2050 của thiệt hại GDP (% độ lệch so với đường cơ sở) cho hai kịch bản khí hậu RCP 2.6 (đường xanh đậm) và RCP 4.5 (đường cam). Hai đường gần trùng nhau đến khoảng 2032, xuất phát xấp xỉ 6-7% năm 2022; sau đó RCP 4.5 cao hơn, đạt xấp xỉ 12,4% năm 2050 còn RCP 2.6 đạt xấp xỉ 10% năm 2050 (văn bản: 9,8% và 12,3%).")
add(32,"table","Bảng 2","Ước tính nhu cầu tài chính tăng thêm cho các biện pháp thích ứng, 2022–2050","Bảng 2. Các cột: Trung bình mỗi năm (% GDP) | Giá trị tích lũy (tỷ USD tính theo NPV). Nhu cầu tài chính tăng thêm: 4,5–5,4 | 342,3–410,7. Tổng nhu cầu tài chính: 6,3–7,2 | 479,2–547,6. Nhu cầu đầu tư cho các tài sản tư nhân có khả năng phục hồi: 3,0 | 228,2. Đầu tư mới và bổ sung thêm cơ sở hạ tầng có khả năng phục hồi: 3,0–3,5 | 228,2–266,2. Hỗ trợ tài chính cho người dân và doanh nghiệp bị ảnh hưởng: 0,3–0,7 | 22,8–53,2. Nguồn tài chính hiện có: 1,8 | 136,9. Ghi chú: NPV là giá trị hiện tại thuần; số liệu phản ánh tỷ lệ chiết khấu 6%.")
add(37,"figure","Hình 9","Mức độ dễ bị ảnh hưởng khi gặp thiên tai của các tuyến đường có quy mô quốc gia tại Việt Nam","Ba bản đồ Việt Nam đặt cạnh nhau: 'Lở đất' (màu cam), 'Lũ lụt 1.000 năm' (màu xanh dương) và 'Bão lũ' (màu xanh lá). Chú giải 'Percentage exposure' gồm các lớp 0 đến 10, 10 đến 20, 20 đến 30, 30 đến 40, 40 đến 100 và 'No value'; màu càng đậm càng bị ảnh hưởng nhiều. Bản đồ Lở đất có các vùng màu cam đậm nhất tập trung ở dải miền Trung ven biển và Tây Nguyên; bản đồ Lũ lụt 1.000 năm có các vùng xanh đậm rải rác dọc ven biển và ở Đồng bằng sông Cửu Long; bản đồ Bão lũ có màu xanh lá đậm tập trung dọc bờ biển phía Bắc và miền Trung. Nguồn: Oh và đồng sự, 2019.")
add(40,"figure","Hình 10","Đồng bằng sông Cửu Long có nguy cơ cao với tình trạng nước biển","Bản đồ màu xanh dương của khu vực sông Mekong (ĐBSCL), tiêu đề phụ 'Dự báo tình trạng ngập mặn do triều cường vào năm 2050 tại khu vực sông Mekong'. Màu xanh càng đậm là khu vực càng bị ngập; có nhãn CAM PU CHIA ở phía Tây Bắc và BIỂN ĐÔNG ở phía Đông Nam. Phần lớn diện tích đồng bằng có màu xanh, cho thấy nguy cơ ngập rộng khắp. Nguồn: Ngân hàng Thế giới.")
add(42,"figure","Hình 11","Rủi ro ngập lụt tại các vùng ven biển","Bản đồ Việt Nam theo tỉnh, tô màu xanh lá theo 'Relative Flood Risk' gồm năm lớp từ nhạt đến đậm (từ 0 đến 1; lớp đậm nhất khoảng 0,66 đến 1). Các điểm đánh dấu thành phố: Hanoi, Haiphong, Da Nang, Ho Chi Minh City, Can Tho. Các tỉnh màu đậm nhất tập trung ở dải duyên hải miền Trung quanh Da Nang; nhiều tỉnh phía Nam và Tây Nguyên có màu nhạt. Nguồn: Ngân hàng Thế giới.")
add(50,"table","Bảng 3","Nhu cầu đầu tư và lợi nhuận đầu ra theo Lộ trình phát thải carbon ròng bằng '0' (NZP)","Bảng 3 (tỷ USD theo NPV; chiết khấu 6%). Các cột: 2022–2030 | 2031–2040 | 2022–2040. NZP: Nhu cầu đầu tư 31,8 | 49,5 | 81,3. Mức sản lượng tăng -7,6 | -46,0 | -53,7. Tác động kinh tế ròng -39,4 | -95,5 | -134,9. NZP với những cải cách hỗ trợ: Nhu cầu đầu tư 31,8 | 49,5 | 81,3. Mức sản lượng tăng 11,3 | 68,7 | 80,1. Tác động kinh tế ròng -20,5 | 19,3 | -1,3.")
add(53,"table","Bảng 4","Các chính sách hỗ trợ chính sẽ ảnh hưởng như thế nào đến tác động của NZP đối với phát thải khí nhà kính và GDP","Bảng 4 (phần trăm thay đổi so với cơ sở). Các cột: Tỷ lệ thay đổi mức phát thải khí nhà kính (%) năm 2030 | năm 2040; Tỷ lệ thay đổi GDP (%) năm 2030 | năm 2040. NZP không có cải cách: -42,8 | -73,6 | -0,6 | -2,2. NZP và giảm ô nhiễm không khí: -42,2 | -73,4 | 0,8 | -1,0. NPZ và tăng khả năng cạnh tranh: -42,7 | -71,8 | 0,9 | -0,6. NZP và tăng hiệu quả năng lượng: -41,9 | -72,1 | 0,5 | 0,2. NZP và cải thiện sự dịch chuyển lao động: -43,0 | -71,8 | -0,2 | -0,2. NZP và hạn chế lấn át các khoản đầu tư khác: -43,1 | -73,5 | -0,5 | -0,9. NZP và tất cả các biện pháp hỗ trợ: -40,2 | -71,9 | 1,7 | 3,3.")
add(54,"figure","Hình 12","Ngành điện Việt Nam phụ thuộc rất nhiều vào than","Hai biểu đồ vành khuyên (donut) năm 2020. Bên trái: công suất lắp đặt theo loại hình nhiên liệu hóa thạch, tổng 68 GW: Than đá 30%, Thủy điện 30%, Năng lượng tái tạo 25%, Khí đốt 13% (phần còn lại khoảng 2%). Bên phải: điện năng sản xuất từ nhiên liệu hóa thạch, tổng 200 TWh: Than đá 59%, Thủy điện 20%, Khí đốt 17% (năng lượng tái tạo và phần còn lại khoảng 4%). Nguồn: Ngân hàng Thế giới, dựa trên dữ liệu của Bộ Công Thương và EVN.")
add(56,"figure","Hình 13","So sánh nguồn điện và phát thải GHG giữa CPS và ADS","Hai biểu đồ. Bên trái: cột xếp chồng 'Điện được sản xuất năm 2040 (TWh)' cho ba kịch bản BAU, CPS, ADS với tổng 922, 788 và 812 TWh. Điện than: BAU 550, CPS 276, ADS 26. Điện khí: BAU 106, CPS 188, ADS 124. ADS có tỷ trọng gió ngoài khơi, gió gần bờ, mặt trời và thủy điện lớn hơn. Bên phải: biểu đồ đường 'Phát thải GHG ngành điện, triệu tấn CO2e, 2020-40': CPS tăng đến đỉnh xấp xỉ 275 quanh năm 2034 rồi còn 246 vào 2040; ADS đạt đỉnh xấp xỉ 148 quanh 2030 rồi giảm còn 63 vào 2040; cả hai bắt đầu xấp xỉ 100 năm 2020.")
add(56,"table","Bảng 5 (phần đầu)","Nhu cầu đầu tư và Chi phí kinh tế: Kịch bản tăng tốc khử carbon (ADS), 2022–2040","Bảng 5: NPV, độ chênh lệch giữa CPS (đường cơ sở) và ADS; cột tỷ USD | Thay đổi. Chi phí vốn để lưu trữ và phát điện mới: +44 | +52%. Trong đó: Than đá -19 | -72%. Khí đốt -8 | -42%.")
add(57,"table","Bảng 5 (phần sau)","Nhu cầu đầu tư và Chi phí kinh tế: Kịch bản tăng tốc khử carbon (ADS), 2022–2040 (tiếp)","Bảng 5 (tiếp, tỷ USD | Thay đổi): Mặt trời +21 | +429%. Gió (trên bờ) +8 | +55%. Gió (ngoài khơi) +39 | +402%. Thủy điện và các năng lượng tái tạo khác ~0 | +4%. Lưu trữ (ắc quy và thủy điện tích năng) +3 | Không có sẵn. Chi phí nâng cấp và mở rộng mạng lưới +13 | +52%. Chi phí vận hành và bảo trì thay đổi +2 | +40%. Chi phí vận hành và bảo trì cố định +6 | +12%. Tổng chi phí +65 | 56%. Trừ khoản tiết kiệm chi phí nhiên liệu -32 | -31%. Tổng chi phí ròng +33 | +13%. Chi phí thiệt hại môi trường địa phương -14 | -40%. Chi phí thiệt hại môi trường toàn cầu -40 | -37%.")
add(59,"figure","Hình 14","Sản xuất than nội địa của Việt Nam tập trung ở các vùng núi phía Bắc","Bản đồ sơ đồ miền Bắc Việt Nam với các hình elip màu cam đánh dấu các vùng sản xuất than: Sông Đà, Sông Cả và Nghệ Tĩnh, Đồng bằng sông Hồng, Thái Nguyên, Na Dương. Có đánh dấu Hà Nội, các điểm Hòn Gai và Cẩm Phả (vòng tròn đỏ), và Quảng Ninh được chú thích là 'Tỉnh sản xuất than chính'. Nguồn: Ngân hàng Thế giới dựa trên thông tin của chính phủ.")
add(62,"figure","Hình 15","Giảm phát thải CO2 vào năm 2030 trong kịch bản giảm nhẹ, so với BAU","Biểu đồ vùng xếp chồng (nghìn tấn CO2) từ 2014 đến 2030, giá trị âm (giảm phát thải) từ 0 xuống xấp xỉ -19.500 đến -20.000 nghìn tấn vào năm 2030 (trục từ 0 đến -25.000). Chú giải 12 biện pháp: 1.1 Tiết kiệm nhiên liệu và tiêu chuẩn khí thải mới; 1.3 Cải thiện hệ số tải trọng xe tải; 2.1 Mở rộng hệ thống xe buýt; 2.2 Mở rộng hệ thống xe buýt BRT; 2.3 Triển khai hệ thống tàu điện ngầm; 3.1/3.2 Chuyển đổi phương thức từ đường bộ sang ĐTNĐ/Ven biển; 3.3 Chuyển đổi phương thức từ đường bộ sang đường sắt; 4.1 Khuyến khích nhiên liệu sinh học (E5); 4.2 Khuyến khích xe máy điện; 4.3 Khuyến khích xe bus CNG; 4.4 Khuyến khích ô tô điện; 4.4 Khuyến khích xe bus điện. Dải rộng nhất, màu xanh nhạt, là 4.2 Khuyến khích xe máy điện.")
add(65,"figure","Hình 16","Các biện pháp hiệu quả về mặt chi phí để giảm phát thải khí nhà kính từ sản xuất lúa gạo","Biểu đồ cột (đơn vị $/tCO2e, trục từ -200 đến 500) cho 11 biện pháp. Chi phí âm (tiết kiệm): Chuyển từ trồng lúa sang nuôi tôm (xấp xỉ -80); Cải tạo đất trồng lúa thường thành đất trồng lúa nước (xấp xỉ -40); Mô hình tưới lúa ướt khô xen kẽ (AWD) ở ĐB sông Cửu Long (xấp xỉ -20); Mô hình AWD ở Đồng bằng sông Hồng (xấp xỉ -15). Xấp xỉ 0: Chuyển đổi từ trồng lúa sang trồng hoa màu. Chi phí dương: Cải thiện quản lý rơm rạ (xấp xỉ 15); Quản lý cây trồng tổng hợp (ICM) cho lúa (xấp xỉ 20); Mô hình AWD và Hệ thống SRI/1M5R ở khu trồng lúa tưới tiêu vừa phải (xấp xỉ 65); Mô hình AWD và Hệ thống SRI/1M5R ở khu trồng lúa tưới tiêu hạn chế (xấp xỉ 90); Chuyển từ trồng lúa sang trồng ngô (xấp xỉ 390, cao nhất).")
add(65,"figure","Hình 17","Các biện pháp hiệu quả về mặt chi phí để giảm phát thải khí nhà kính từ chăn nuôi","Biểu đồ cột (đơn vị $/tCO2e, trục từ -200 đến 800) cho 9 biện pháp. Chi phí âm: Khẩu phần hỗn hợp hoàn chỉnh dành cho bò sữa (TMR) (xấp xỉ -130); Bổ sung chế độ ăn uống cho bò nuôi lấy thịt (TMR) (xấp xỉ -110). Xấp xỉ 0: Ủ chất thải của lợn; Thu khí ga sinh học từ chất thải chăn nuôi lợn (TMR). Dương: Xử lý chất thải gia súc khác (xấp xỉ 15); Cải thiện chất lượng khẩu phần ăn cho gia súc nhỏ (xấp xỉ 150); Cải thiện chất lượng khẩu phần ăn cho bò nuôi lấy thịt (xấp xỉ 155); Cải thiện chất lượng khẩu phần ăn cho bò sữa (xấp xỉ 310); Cải thiện chất lượng khẩu phần ăn cho trâu nuôi lấy thịt (TMR) (xấp xỉ 730, cao nhất).")
add(70,"figure","Hình 18","Tác động của NZP đối với tình trạng đói nghèo, an ninh kinh tế và bất bình đẳng (sai lệch so với BAU) vào năm 2040","Biểu đồ cột (màu cam), giá trị in trên cột: Mức nghèo ($3,20): -0,1; Kinh tế không ổn định ($5,50): -0,1; Bất bình đẳng (Chỉ số Gini): -1,1. Trục tung là sai số so với kịch bản phát triển thông thường (BAU).")
add(71,"figure","Hình 19","Chỉ số giá theo nhóm hàng hóa, 2022–2040 (% lệch so với BAU)","Biểu đồ đường 2022-2040 cho sáu nhóm: Năng lượng, Công nghiệp, Dịch vụ, Vận tải, Lương thực, Y tế. Năng lượng cao nhất: từ xấp xỉ 3,7% (2022) tăng lên xấp xỉ 15% (2040). Vận tải xấp xỉ 4,5% vào 2040. Các nhóm còn lại gần 0; Y tế xấp xỉ -1,5% vào 2040. Nguồn: Ngân hàng Thế giới, mô hình CGE.")
add(72,"figure","Hình 20","Những thay đổi về việc làm theo lĩnh vực vào năm 2040","Biểu đồ cột (% chuyển việc làm, độ lệch so với BAU) cho hai kịch bản 'NZP' và 'NZP đã cải cách' theo lĩnh vực (NZP / NZP đã cải cách): Điện 0 / 23,6; Khai thác mỏ 2,2 / 18,4; Vận tải -6,3 / 7,9; Xây dựng 1,7 / 9,8; Công nghiệp -0,4 / 7,4; Dịch vụ 0,1 / 12,4; Thương mại 0,4 / -5,4; Nông nghiệp 0 / -5,4; Không hoạt động 0,1 / -0,7.")
add(77,"figure","Hình 21","Nhu cầu và các nguồn tài chính tiềm năng giai đoạn 2022–2040","Sơ đồ cây (diagram): khối trên 'NHU CẦU TÀI CHÍNH 368 tỷ USD' (Khả năng chống chịu: 4,7% GDP mỗi năm; Khử carbon: 2,1% GDP mỗi năm) chia ra ba nguồn: KHU VỰC TƯ NHÂN 184 tỷ USD (~3,4% GDP mỗi năm); KHU VỰC CÔNG 130 tỷ USD (~2,4% GDP mỗi năm); BÊN NGOÀI 54 tỷ USD (~1% GDP mỗi năm). Ghi chú: NPV chiết khấu ở tỷ lệ 6%.")
add(78,"figure","Hình 22","Dư nợ cho vay tư nhân về vấn đề khí hậu và tín dụng xanh từ 2016 đến 2019 (tỷ USD)","Bên trái: biểu đồ cột 'Dư nợ tín dụng xanh' (tỷ USD): 2016: 3,7; 2017: 7,8; 2018: 10,3; 2019: 13,9; 2020: 14,5; 2021:Q1: 14,5. Bên phải: biểu đồ cột nhóm 'Tín dụng xanh theo lĩnh vực' (trục đến 188) cho 2019, 2020, 2020:Q1 với ba nhóm Nông nghiệp xanh, Năng lượng tái tạo xanh, Khác (bao gồm quản lý nước, lâm nghiệp bền vững). Nguồn: FiinResearch và NHNN.")
add(84,"table","Bảng 6","Tiêu chí ưu tiên","Bảng 6: ma trận Khẩn cấp (hàng) x Tác động (cột). Khẩn cấp Cao ('Trì hoãn hành động làm tăng chi phí đạt cùng mục tiêu'): Tác động Cao = 'Những hành động không thể trì hoãn và sẽ có tác động lớn và ngay lập tức (thắng nhanh)'; Tác động Trung bình = 'Các hành động có thể cần lên kế hoạch dài hạn và huy động sự ủng hộ chính trị và nguồn tài chính'. Khẩn cấp Trung bình ('Chậm trễ hành động không làm tăng chi phí đạt cùng mục tiêu'): Tác động Cao = 'Các hành động cần thời gian để hình thành và thực hiện nhưng có thể mang lại tác động lớn'; Tác động Trung bình = 'Những hành động cần thời gian để hình thành và thực hiện; tác động có thể không chắc chắn trong một số trường hợp'. Cột Tác động Cao: 'Hành động có tác động tức thì và tạo điều kiện để đạt được các mục tiêu phát triển khác'; Tác động Trung bình: 'Hành động mà các tác động sẽ xảy ra trong vài thập kỷ'.")
add(91,"table","Phụ lục 1","Dữ liệu Khí hậu và Phát triển chính của Việt Nam","Phụ lục 1 (trang đầu). Mỗi chỉ số có ba cặp giá trị-năm. GDP bình quân đầu người (tốc độ tăng trưởng hàng năm) %: 5,1 (1990), 7,5 (2005), 2,9 (2020), nguồn WDI. Năng suất lao động (tốc độ tăng hàng năm) %: -, -, 6,9 (2020), OECD. Sản lượng kinh tế phi chính thức % GDP: 23,0 (1990), 15,2 (2005), 11,6 (2018), WBG. Thất nghiệp trung bình % lao động: 1,8 (1991), 2,1 (2005), 2,2 (2020). Cán cân vãng lai % GDP: -, -0,9 (2005), -5,5 (2020). Trợ cấp trước thuế cho nhiên liệu hóa thạch USD/người: 0,9 (2015), 5,1 (2017), 2,8 (2019). Mức độ xuất khẩu than (Mst, triệu tấn non): 2.910 (1990), 15.138 (2005), 982 (2020). Mức xuất khẩu dầu (triệu thùng/ngày): 53,0 (1990), 361,0 (2005), 67,0 (2020). Phát thải bình quân đầu người (tấn CO2e/người): 0,3 (1990), 1,1 (2005), 2,7 (2018). Tổng lượng phát thải khí nhà kính, bao gồm LUCF (triệu tấn CO2e): 1,17 (1990), 207,64 (2005), 364,43 (2018). Nông nghiệp: 46,34 (1990), 65,9 (2005), 70,99 (2018). Xây dựng: 1,97; 9,88; 15,79. Điện/nhiệt: 4,88; 24,28; 109,13. Khí thoát ra: 0,66; 12,85; 18,66. Quy trình công nghiệp: 1,06; 13,15; 37,13. Chế biến, chế tạo/xây dựng: 5,66; 24,06; 63,91. Đốt cháy nhiên liệu khác: 5,35; 4,96; 4,21. Vận tải: 4,17; 19,36; 36,32. Rác thải: 2,46; 13,5; 20,4. Thay đổi sử dụng đất và lâm nghiệp: -71,38 (1990); 19,69 (2005); -12,09 (2018). Nguồn: Climatewatch.")
